int cifs_search_next(int xid, struct cifs_tcon *tcon, __u16 searchHandle, struct cifs_search_info *psrch_inf) {
    int rc = -EINVAL;

    if (!tcon || !psrch_inf) {
        return rc;
    }

    if (searchHandle == 0) {
        return -EINVAL;
    }

    if (psrch_inf->max_entries < 0 || psrch_inf->max_entries > CIFS_MAX_SRCH_ENTRIES) {
        return -EINVAL;
    }

    if (psrch_inf->max_entries == 0) {
        psrch_inf->end_of_search = true;
        return 0;
    }

    rc = cifs_call_server(xid, tcon, searchHandle, psrch_inf);

    if (rc < 0) {
        return rc;
    }

    if (psrch_inf->entries_found == 0) {
        psrch_inf->end_of_search = true;
    }

    return 0;
}
